<style
  scoped
  lang="scss"
  src="./gms-configure-report-modal-general-tab.scss"
></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import SelectionMenu from "../../selection-menu/selection-menu";
import { SelectionMenuMode } from "../../selection-menu/selection-menu.constants";
import ToggleSwitch from "../../toggle-switch/toggle-switch";
import Select from "../../select/select";

@Component({
  components: {
    Select,
    SelectionMenu,
    ToggleSwitch,
  },
})
export default class GmsConfigureReportGeneralTab extends Vue {
  @Prop({
    type: String,
  })
  focus;

  @Prop({
    type: String,
    default: "",
  })
  initialReportTitle;

  @Prop({
    type: String,
    default: "",
  })
  initialVisibility;

  @Prop({
    type: Boolean,
    default: false,
  })
  initialRollUp;

  @Prop({
    type: Object,
    default: () => ({ placeholder: "", options: [] }),
  })
  visibilityConfig;

  // ENUMS
  SelectionMenuMode = SelectionMenuMode;

  // DATA
  reportName = "";
  visibility = "";

  beforeMount() {
    this.reportName = this.initialReportTitle;
    this.visibility = this.initialVisibility;
  }

  handleReportNameChange() {
    this.$emit("reportNameChange", this.reportName);
  }

  handleVisibilityChange(newVisibility) {
    this.visibility = newVisibility;
    this.$emit("visibilityChange", newVisibility);
  }

  handleRollUpChange(newRollUp) {
    this.$emit("rollUpChange", newRollUp);
  }
}
</script>

<template>
  <div class="GeneralTab">
    <h4 class="GeneralTab__Title">General Report Options</h4>
    <div class="GeneralTab__Row">
      <div class="GeneralTab__Row-Title">Report Title</div>
      <input
        class="GeneralTab__Row-Input"
        type="text"
        placeholder="New Custom Report"
        @input="handleReportNameChange"
        v-model="reportName"
      />
      <!-- displays the focus. e.g. Donors -->
      <template v-if="focus">
        <div class="GeneralTab__Row-Title">Focus is</div>
        <p class="GeneralTab__Focus">
          {{ focus }}
        </p>
      </template>
    </div>
    <div class="GeneralTab__Row">
      <div class="GeneralTab__Row-Title">Visibility</div>
      <Select
        class="GeneralTab__Row-Menu"
        label="Visibility"
        search
        :items="visibilityConfig.options"
        :value="visibility"
        @select="handleVisibilityChange"
      />
    </div>
    <div class="GeneralTab__Row">
      <div class="GeneralTab__Switch">
        <ToggleSwitch :value="initialRollUp" @switch="handleRollUpChange" />
        Roll-up All Locations
      </div>
    </div>
  </div>
</template>
